export function uniqueDisplayNames(values: readonly string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of values) {
    if (seen.has(raw)) {
      continue;
    }
    seen.add(raw);

    const display = raw
      .normalize("NFKC")
      .replace(/\p{White_Space}+/gu, " ")
